<script setup>

const route = useRoute();
const slug = route.params.slug;

const { data: article, pending, error } = await useFetch(`https://painel.gsadmin.app/items/articles?filter[slug][_eq]=${slug}`, {
  method: "GET",
  key: `article-${slug}`, // importante para cache único por slug
  headers: {
    "Content-Type": "application/json"
  }, 
  transform: (data) => {
    return {
      title: data[0]?.title,
      content: data[0]?.content,
    };
  },
});

</script>

<template>
  <div v-if="pending">Carregando...</div>
  <div v-else-if="error">Erro: {{ error.message }}</div>
  <div v-else>
    <!-- Renderizar seu artigo aqui -->
    <h1>{{ title }}</h1>
    <div v-html="article.data[0]?.content"></div>
  </div>
</template>



